const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function maskStatistics(prob,width,height){let n=0,xs=0,ys=0,left=width,top=height,right=0,bottom=0,conf=0;for(let i=0;i<prob.length;i++)if(prob[i]>.7){const x=i%width,y=Math.floor(i/width);n++;xs+=x;ys+=y;conf+=prob[i];left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}const area=n/(width*height);return n&&area>.015&&area<.92?{area,confidence:conf/n,center:{x:xs/n/width,y:ys/n/height},box:{x:left/width,y:top/height,w:(right-left+1)/width,h:(bottom-top+1)/height}}:null}
function rgb(frame,x,y){const i=(clamp(Math.round(y),0,frame.height-1)*frame.width+clamp(Math.round(x),0,frame.width-1))*3;return frame.pixels.subarray?frame.pixels.subarray(i,i+3):frame.pixels.slice(i,i+3)}
const dist=(a,b)=>(Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2]))/765;
export function findCircleWindows(frame){const{width:w,height:h}=frame;if(w<40||h<40)return[];const gray=new Float32Array(w*h);for(let i=0;i<gray.length;i++)gray[i]=(frame.pixels[i*3]+frame.pixels[i*3+1]+frame.pixels[i*3+2])/765;const tmp=new Float32Array(w*h),smooth=new Float32Array(w*h),kernel=[1,4,6,4,1];for(let y=0;y<h;y++)for(let x=0;x<w;x++){let v=0;for(let k=-2;k<=2;k++)v+=gray[y*w+clamp(x+k,0,w-1)]*kernel[k+2];tmp[y*w+x]=v/16}for(let y=0;y<h;y++)for(let x=0;x<w;x++){let v=0;for(let k=-2;k<=2;k++)v+=tmp[clamp(y+k,0,h-1)*w+x]*kernel[k+2];smooth[y*w+x]=v/16}const edges=[];for(let y=2;y<h-2;y+=2)for(let x=2;x<w-2;x+=2){const dx=smooth[y*w+x+1]-smooth[y*w+x-1],dy=smooth[(y+1)*w+x]-smooth[(y-1)*w+x],m=Math.hypot(dx,dy);if(m>.08)edges.push({x,y,dx:dx/m,dy:dy/m})}const radii=[];for(let r=Math.max(12,Math.round(Math.min(w,h)*.15));r<=Math.min(w,h)*.36;r+=2)radii.push(r);const candidates=[];for(const radius of radii){const votes=new Uint16Array(w*h);for(const e of edges)for(const sign of [-1,1]){const cx=Math.round(e.x+sign*radius*e.dx),cy=Math.round(e.y+sign*radius*e.dy);if(cx>radius&&cy>radius&&cx<w-radius&&cy<h-radius)for(let yy=-1;yy<=1;yy++)for(let xx=-1;xx<=1;xx++)votes[(cy+yy)*w+cx+xx]++}const peaks=[];for(let i=0;i<votes.length;i++)if(votes[i]>=8)peaks.push({at:i,votes:votes[i]});peaks.sort((a,b)=>b.votes-a.votes);const centers=[];for(const peak of peaks){const xx=peak.at%w,yy=Math.floor(peak.at/w);if(centers.every(c=>Math.hypot(c.x-xx,c.y-yy)>8)){centers.push({x:xx,y:yy});if(centers.length>=8)break}}for(const{x,y}of centers){let support=0,inner=[];for(let i=0;i<64;i++){const a=i*Math.PI/32,c=Math.cos(a),s=Math.sin(a);let edge=0;for(let dr=-2;dr<=2;dr++)edge=Math.max(edge,dist(rgb(frame,x+c*(radius+dr-2),y+s*(radius+dr-2)),rgb(frame,x+c*(radius+dr+2),y+s*(radius+dr+2))));if(edge>.13)support++;inner.push(...rgb(frame,x+c*radius*.55,y+s*radius*.55))}const means=[0,1,2].map(c=>inner.filter((_,i)=>i%3===c).reduce((s,v)=>s+v,0)/(inner.length/3)),variance=inner.reduce((s,v,i)=>s+(v-means[i%3])**2,0)/inner.length/65025;if(support/64>.78&&variance>.008)candidates.push({x:x/w,y:y/h,r:radius/w,ry:radius/h,support:support/64})}}const border=[[],[],[]];for(let x=0;x<w;x+=4)for(const y of [0,h-1]){const v=rgb(frame,x,y);for(let c=0;c<3;c++)border[c].push(v[c])}for(let y=0;y<h;y+=4)for(const x of [0,w-1]){const v=rgb(frame,x,y);for(let c=0;c<3;c++)border[c].push(v[c])}const background=border.map(a=>a.sort((x,y)=>x-y)[Math.floor(a.length/2)]),seen=new Uint8Array(w*h),queue=new Int32Array(w*h),foreground=new Uint8Array(w*h);for(let y=0;y<h;y++)for(let x=0;x<w;x++)foreground[y*w+x]=dist(rgb(frame,x,y),background)>.18?1:0;for(let i=0;i<foreground.length;i++){if(seen[i]||!foreground[i])continue;let head=0,tail=1,left=w,top=h,right=0,bottom=0;seen[i]=1;queue[0]=i;while(head<tail){const k=queue[head++],x=k%w,y=Math.floor(k/w);left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);for(const n of [x>0?k-1:-1,x<w-1?k+1:-1,y>0?k-w:-1,y<h-1?k+w:-1])if(n>=0&&!seen[n]&&foreground[n]){seen[n]=1;queue[tail++]=n}}const bw=right-left+1,bh=bottom-top+1,r=(bw+bh)/4;if(r<Math.min(w,h)*.15||bw/bh<.8||bw/bh>1.2||tail/(bw*bh)<.6||tail/(bw*bh)>.88)continue;const x=(left+right)/2,y=(top+bottom)/2,values=[];let support=0;for(let j=0;j<64;j++){const a=j*Math.PI/32,c=Math.cos(a),ss=Math.sin(a);if(dist(rgb(frame,x+c*(r-2),y+ss*(r-2)),rgb(frame,x+c*(r+2),y+ss*(r+2)))>.13)support++;values.push(...rgb(frame,x+c*r*.55,y+ss*r*.55))}const means=[0,1,2].map(c=>values.filter((_,i)=>i%3===c).reduce((s,v)=>s+v,0)/(values.length/3)),variance=values.reduce((s,v,j)=>s+(v-means[j%3])**2,0)/values.length/65025;if(support/64>.78&&variance>.008)candidates.push({x:x/w,y:y/h,r:r/w,ry:r/h,support:support/64,method:'closed-region'})}const result=[];for(const c of candidates.sort((a,b)=>(Number(b.method==='closed-region')-Number(a.method==='closed-region'))||b.support-a.support))if(!result.some(b=>Math.hypot((b.x-c.x)*w,(b.y-c.y)*h)<12&&Math.abs((b.r-c.r)*w)<10))result.push(c);return result.slice(0,3)}
function patchError(a,b,ax,ay,bx,by){let error=0;for(let y=-3;y<=3;y++)for(let x=-3;x<=3;x++){const i=((ay+y)*a.width+ax+x)*3,j=((by+y)*b.width+bx+x)*3;error+=Math.abs(a.pixels[i]-b.pixels[j])+Math.abs(a.pixels[i+1]-b.pixels[j+1])+Math.abs(a.pixels[i+2]-b.pixels[j+2])}return error/(49*765)}
export function trackFeatures(frames){if(frames.length<4)return[];const first=frames[0],w=first.width,h=first.height,candidates=[];for(let y=10;y<h-10;y+=8)for(let x=10;x<w-10;x+=8){const a=rgb(first,x-3,y-3),b=rgb(first,x+3,y-3),c=rgb(first,x-3,y+3),d=rgb(first,x+3,y+3),quality=Math.min(dist(a,b)+dist(c,d),dist(a,c)+dist(b,d));if(quality>.04)candidates.push({x,y,quality})}candidates.sort((a,b)=>b.quality-a.quality);const selected=[],cells=new Set();for(const p of candidates){const cell=Math.floor(p.x/(w/4))+','+Math.floor(p.y/(h/3));if(!cells.has(cell)){selected.push(p);cells.add(cell)}}for(const p of candidates)if(selected.every(s=>Math.hypot(s.x-p.x,s.y-p.y)>14)){selected.push(p);if(selected.length>=20)break}const tracks=[];for(const point of selected){let x=point.x,y=point.y;const path=[{time:first.time,x:x/w,y:y/h}];for(let k=1;k<frames.length;k++){const a=frames[k-1],b=frames[k];if(b.time-a.time>1.6||b.width!==w||b.height!==h)break;let best={error:Infinity};for(let dy=-12;dy<=12;dy++)for(let dx=-12;dx<=12;dx++){const xx=x+dx,yy=y+dy;if(xx<4||yy<4||xx>=w-4||yy>=h-4)continue;const error=patchError(a,b,x,y,xx,yy),cost=error+.00001*(dx*dx+dy*dy);if(cost<(best.cost??Infinity))best={error,cost,x:xx,y:yy}}if(best.error>.045)break;const reverse=patchError(b,a,best.x,best.y,x,y);if(reverse>.045)break;x=best.x;y=best.y;path.push({time:b.time,x:x/w,y:y/h,error:best.error})}if(path.length>=4)tracks.push({path})}return tracks}
export function followEvidence(textTracks,featureTracks){const median=a=>[...a].sort((x,y)=>x-y)[Math.floor(a.length/2)]||0,globalX=median(featureTracks.map(f=>f.path.at(-1).x-f.path[0].x)),globalY=median(featureTracks.map(f=>f.path.at(-1).y-f.path[0].y));const results=[];for(const text of textTracks||[]){if(text.observations.length<4||!text.moving)continue;for(const feature of featureTracks){const pairs=text.observations.map(t=>{const f=feature.path.reduce((a,b)=>Math.abs(b.time-t.time)<Math.abs(a.time-t.time)?b:a);return Math.abs(f.time-t.time)<.3?{t,f}:null}).filter(Boolean);if(pairs.length<4)continue;const inside=pairs.some(({t,f})=>f.x>=t.box.x-.025&&f.x<=t.box.x+t.box.w+.025&&f.y>=t.box.y-.025&&f.y<=t.box.y+t.box.h+.025);if(inside)continue;const dx=pairs.map(({t,f})=>t.box.x+t.box.w/2-f.x),dy=pairs.map(({t,f})=>t.box.y+t.box.h/2-f.y),avg=a=>a.reduce((s,v)=>s+v,0)/a.length,spread=a=>Math.sqrt(avg(a.map(v=>(v-avg(a))**2)));if(Math.hypot(spread(dx),spread(dy))<.018){const p=pairs[0],q=pairs.at(-1);if(Math.hypot(q.f.x-p.f.x,q.f.y-p.f.y)<.05)continue;if(Math.hypot(globalX,globalY)>.04&&Math.hypot((q.f.x-p.f.x)-globalX,(q.f.y-p.f.y)-globalY)<.02)continue;results.push({text:text.text,start:p.t.time,end:q.t.time,path:pairs.map(({t,f})=>({time:t.time,text:{x:t.box.x+t.box.w/2,y:t.box.y+t.box.h/2},target:{x:f.x,y:f.y}}))});break}}}return results}
